/// One tool call dispatched by the agent during a turn.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolCall {
    pub id: ToolCallId,
    pub name: ToolName,
    pub args_json: Value,
}

/// Result of a completed tool call.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolResult {
